      const n = nearestIndex(built.samples, hint.x, hint.z, 0);
      const s = built.samples[n.index];
      const latOff = east ? built.width + 18 + built.width / 2 + extra : -(built.width / 2 + extra);
      return { x: s.x + s.rx * latOff, z: s.z + s.rz * latOff, y: s.y };
