      const beam = new THREE.Mesh(new THREE.BoxGeometry(built.width + 2.4, 0.7, 1.15), conc);
      beam.position.set(s.x, s.y + 9.3, s.z);
      beam.rotation.y = Math.atan2(s.rx, s.rz);
